# The formula of factory, generated by factory's scripts/formula.sh from the checksums of
# its 5.0.1 release, whose archives are copied to a factory-<version> release of this
# repository (factory's repository is private). Never edited by hand.
class Factory < Formula
  desc "Records and gates work: missions, sessions, proofs, mandates, delivery"
  # factory's repository is private, and brew audit requires a homepage that answers.
  homepage "https://github.com/FunDrivenDev/homebrew-tap"
  version "5.0.1"

  on_macos do
    on_arm do
      url "https://github.com/FunDrivenDev/homebrew-tap/releases/download/factory-#{version}/factory_#{version}_darwin_arm64.tar.gz"
      sha256 "5f9104fec29aa545c8c576517114beca0d6f1f75e8295ecef520821f5b6bc369"
    end
    on_intel do
      url "https://github.com/FunDrivenDev/homebrew-tap/releases/download/factory-#{version}/factory_#{version}_darwin_amd64.tar.gz"
      sha256 "e412efa7c82bc0c75b9bc6fd5b6eb3f9f81ccf674b32b53bb94c338316f06aa0"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/FunDrivenDev/homebrew-tap/releases/download/factory-#{version}/factory_#{version}_linux_arm64.tar.gz"
      sha256 "d9f46822eceac597604954a6d328ca924a8ebee95af6406a41aafa4996e94509"
    end
    on_intel do
      url "https://github.com/FunDrivenDev/homebrew-tap/releases/download/factory-#{version}/factory_#{version}_linux_amd64.tar.gz"
      sha256 "1eea6ee23fbfa29389b86f5d3ce35a3b5fa3e6bc12f080bbf99ec39cba7a4615"
    end
  end

  def install
    bin.install "factory"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/factory --version")
  end
end
